  async listLives(user:{sub:string;role:string}){const admin=['ADMIN','SUPER_ADMIN'].includes(user.role);if(!admin)this.userId(user);const viewer=admin?null:await this.accountForCommunity(user.sub),band=viewer?this.ageBand(viewer.dateOfBirth):null;if(viewer&&band==='UNKNOWN')throw new ForbiddenException('Votre âge doit être renseigné pour consulter les directs.');const rows=await this.prisma.communityLive.findMany({where:{endedAt:null,host:{active:true,suspendedAt:null,deletionScheduledAt:null}},orderBy:{createdAt:'desc'},take:100,include:{host:{select:{id:true,fullName:true,dateOfBirth:true}},participants:{where:{leftAt:null},select:{userId:true,role:true}}}});const result=[];for(const row of rows){if(!admin&&this.ageBand(row.host.dateOfBirth)!==band)continue;if(!admin&&await this.isBlocked(user.sub,row.hostId))continue;result.push({id:row.id,title:row.title,createdAt:row.createdAt,host:{id:row.host.id,displayName:this.displayName(row.host)},viewerCount:Math.max(0,row.participants.length-1),isHost:row.hostId===user.sub});}if(admin)await this.prisma.auditLog.create({data:{userId:user.sub,action:'COMMUNAUTE_DIRECTS_ADMIN_CONSULTES',entity:'CommunityLive',entityId:'ACTIVE',after:{liveCount:result.length}}});return result;}
  async liveAnnouncements(user:{sub:string;role:string}){const id=this.userId(user),since=new Date(Date.now()-24*60*60_000);return this.prisma.userNotification.findMany({where:{userId:id,createdAt:{gte:since},message:'Un direct paroissial vient de commencer. Ouvrez la rubrique Directs pour le découvrir.'},orderBy:{createdAt:'desc'},take:20,select:{id:true,message:true,createdAt:true}});}
  private liveIceServers(){try{const parsed=JSON.parse(process.env.LIVE_ICE_SERVERS_JSON||'[{"urls":"stun:stun.l.google.com:19302"}]');if(!Array.isArray(parsed)||parsed.length>8)throw new Error();const output=parsed.map((server:any)=>{if(!server||typeof server!=='object'||Array.isArray(server))throw new Error();const urls=typeof server.urls==='string'?[server.urls]:server.urls;if(!Array.isArray(urls)||urls.length<1||urls.length>4||urls.some((url:any)=>typeof url!=='string'||!/^(stun|stuns|turn|turns):/i.test(url)))throw new Error();if(('username'in server&&typeof server.username!=='string')||('credential'in server&&typeof server.credential!=='string'))throw new Error();return{urls:server.urls,...(server.username?{username:server.username}:{}),...(server.credential?{credential:server.credential}:{})};});return output;}catch{throw new HttpException('La configuration ICE du direct est invalide.',503);}}
  async startLive(user:{sub:string;role:string;permissions?:string[]},dto:StartLiveDto){const id=this.userId(user);if(!['ADMIN','SUPER_ADMIN'].includes(user.role)&&!user.permissions?.includes('LANCER_LIVE'))throw new ForbiddenException('Le lancement d’un direct nécessite une autorisation paroissiale.');const host=await this.accountForCommunity(id),iceServers=this.liveIceServers();if(this.ageBand(host.dateOfBirth)!=='ADULT')throw new ForbiddenException('Seul un compte adulte peut lancer un direct.');const existing=await this.prisma.communityLive.findFirst({where:{hostId:id,endedAt:null},select:{id:true}});if(existing)throw new HttpException('Vous avez déjà un direct en cours.',409);const live=await this.prisma.$transaction(async tx=>{const created=await tx.communityLive.create({data:{hostId:id,title:dto.title.trim(),participants:{create:{userId:id,role:'HOST'}}}});const recipients=await tx.user.findMany({where:{id:{not:id},role:{in:CHAT_ROLES},active:true,suspendedAt:null,deletionScheduledAt:null},select:{id:true}});if(recipients.length)await tx.userNotification.createMany({data:recipients.map(recipient=>({userId:recipient.id,message:'Un direct paroissial vient de commencer. Ouvrez la rubrique Directs pour le découvrir.'}))});await tx.auditLog.create({data:{userId:id,action:'COMMUNAUTE_DIRECT_LANCE',entity:'CommunityLive',entityId:created.id,after:{notifiedAccounts:recipients.length}}});return created;});return{id:live.id,title:live.title,maxViewers:4,iceServers};}
  async joinLive(user:{sub:string;role:string},liveId:string){const id=this.userId(user),viewer=await this.accountForCommunity(id),iceServers=this.liveIceServers(),live=await this.prisma.communityLive.findFirst({where:{id:liveId,endedAt:null},include:{host:{select:{id:true,dateOfBirth:true}},participants:{where:{leftAt:null},select:{userId:true,role:true}}}});if(!live)throw new NotFoundException('Direct introuvable ou terminé.');if(id===live.hostId)throw new HttpException('Vous diffusez déjà ce direct.',409);const band=this.ageBand(viewer.dateOfBirth);if(band==='UNKNOWN'||band!==this.ageBand(live.host.dateOfBirth)||await this.isBlocked(id,live.hostId))throw new NotFoundException('Direct introuvable ou terminé.');const existing=live.participants.find(p=>p.userId===id);if(existing)return{id:live.id,role:'VIEWER',iceServers};if(live.participants.length>=5)throw new HttpException('Ce direct a atteint sa capacité maximale de quatre spectateurs.',409);await this.prisma.communityLiveParticipant.upsert({where:{liveId_userId:{liveId,userId:id}},update:{role:'VIEWER',joinedAt:new Date(),leftAt:null},create:{liveId,userId:id,role:'VIEWER'}});await this.prisma.communityLiveSignal.create({data:{liveId,senderId:id,targetId:live.hostId,kind:'JOIN',payload:'{}'}});await this.prisma.auditLog.create({data:{userId:id,action:'COMMUNAUTE_DIRECT_REJOINT',entity:'CommunityLive',entityId:liveId}});return{id:live.id,role:'VIEWER',iceServers};}
  async liveSignals(user:{sub:string;role:string},liveId:string,after?:string){const id=this.userId(user);await this.liveMember(liveId,id);let cursor:any=null;if(after){cursor=await this.prisma.communityLiveSignal.findFirst({where:{id:after,liveId,targetId:id},select:{id:true,createdAt:true}});if(!cursor)throw new NotFoundException('Curseur du direct introuvable.');}return this.prisma.communityLiveSignal.findMany({where:{liveId,targetId:id,...(cursor?{OR:[{createdAt:{gt:cursor.createdAt}},{createdAt:cursor.createdAt,id:{gt:cursor.id}}]}:{})},orderBy:[{createdAt:'asc'},{id:'asc'}],take:50,select:{id:true,senderId:true,kind:true,payload:true,createdAt:true}});}
  async sendLiveSignal(user:{sub:string;role:string},liveId:string,dto:LiveSignalDto){const id=this.userId(user),{live,member}=await this.liveMember(liveId,id);const target=await this.prisma.communityLiveParticipant.findUnique({where:{liveId_userId:{liveId,userId:dto.targetId}}});if(!target||target.leftAt||dto.targetId===id)throw new NotFoundException('Participant introuvable.');const allowed=member.role==='HOST'?target.role==='VIEWER'&&['OFFER','ICE'].includes(dto.kind):id!==live.hostId&&dto.targetId===live.hostId&&['JOIN','ANSWER','ICE','LEAVE'].includes(dto.kind);if(!allowed)throw new ForbiddenException('Signalisation WebRTC non autorisée pour cette paire de participants.');if(dto.payload.length>20000)throw new HttpException('Signal WebRTC trop volumineux.',413);if(dto.kind==='JOIN'||dto.kind==='LEAVE'){if(dto.payload!=='{}')throw new HttpException('Signal de contrôle invalide.',400);}else{try{const parsed=JSON.parse(dto.payload);if(!parsed||typeof parsed!=='object'||Array.isArray(parsed))throw new Error();}catch{throw new HttpException('Signal WebRTC invalide.',400);}}await this.prisma.communityLiveSignal.create({data:{liveId,senderId:id,targetId:dto.targetId,kind:dto.kind,payload:dto.payload}});if(dto.kind==='LEAVE')await this.prisma.communityLiveParticipant.update({where:{liveId_userId:{liveId,userId:id}},data:{leftAt:new Date()}});return{queued:true};}
